update waichu_shenqing
set shenpi_zhuangtai = #{shenpiZhuangtai},
    shenpi_ren_id = #{shenpiRenId},
    shenpi_shijian = now(),
    shenpi_yijian = #{shenpiYijian}
where id = #{id}

