set shanchu_zhuangtai = '已删除'
where id = #{id}

update tuizhu_shenqing
set shenpi_zhuangtai = #{shenpiZhuangtai},
    shenpi_ren_id = #{shenpiRenId},
    shenpi_shijian = now(),
    shenpi_yijian = #{shenpiYijian}
where id = #{id}

update tuizhu_shenqing
set shanchu_zhuangtai = '已删除'
where id = #{id}

update chuangwei_shiyong
set shiyong_zhuangtai = '历史',
    jieshu_riqi = curdate(),
    yuanyin = #{yuanyin}
where laoren_id = #{laorenId}
  and shiyong_zhuangtai = '正在使用'
